// File: path/to/src/com.enterprise.billing/module-info.java
module com.enterprise.billing {
    // Mandatory dependency needed at both compile and runtime
    requires java.sql;

    // Compile-time dependency only (optional at runtime)
    requires static lombok;

    // Dependency is required, and any module requiring com.enterprise.billing
    // will automatically read com.enterprise.common
    requires transitive com.enterprise.common;

    // Expose this public API package to any module that requires us
    exports com.enterprise.billing.api;

    // Restrict access of this internal package to a specific friend module
    exports com.enterprise.billing.internal.core to com.enterprise.billing.test;

    // Prevent compile-time coupling, but allow Spring/Hibernate to perform deep reflection
    opens com.enterprise.billing.model to spring.core, org.hibernate.orm.core;
}
